#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T = 1;
    const long long MOD_CONST = 1000000007;

    for (int _ = 0; _ < T; ++_) {
        int total_nodes, factor_value;
        cin >> total_nodes >> factor_value;
        vector<int> k_sequence(total_nodes);
        for (int i = 0; i < total_nodes; ++i) {
            k_sequence[i] = (long long)factor_value * i % total_nodes;
        }

        if (factor_value == 0) {
            cout << (long long)pow(total_nodes, total_nodes - 1) % MOD_CONST << "\n";
            continue;
        }
        if (factor_value == 1) {
            cout << (long long)pow(total_nodes, total_nodes) % MOD_CONST << "\n";
            continue;
        }

        vector<int> visited_flags(total_nodes, 0);
        vector<int> cycle_sizes_count(total_nodes, 0);
        long long result = 1;

        for (int start_point = 0; start_point < total_nodes; ++start_point) {
            if (visited_flags[start_point]) continue;
            int length_of_cycle = 1;
            int current_point = start_point;
            visited_flags[current_point] = 1;
            while (!visited_flags[k_sequence[current_point]]) {
                current_point = k_sequence[current_point];
                visited_flags[current_point] = 1;
                ++length_of_cycle;
            }
            ++cycle_sizes_count[length_of_cycle];
        }

        for (int size = 2; size < total_nodes; ++size) {
            if (cycle_sizes_count[size]) {
                long long total_size = (long long)size * cycle_sizes_count[size] + 1;
                long long power_result = 1;
                long long base = total_size % MOD_CONST;
                long long exponent = cycle_sizes_count[size];
                long long base_pow = base;
                long long exp = exponent;
                while (exp > 0) {
                    if (exp & 1) {
                        power_result = (power_result * base_pow) % MOD_CONST;
                    }
                    base_pow = (base_pow * base_pow) % MOD_CONST;
                    exp >>= 1;
                }
                result = (result * power_result) % MOD_CONST;
            }
        }

        cout << result % MOD_CONST << "\n";
    }
    return 0;
}
